                    return (is_match(p_idx + 2, t_idx) or 
                            (first_match and is_match(p_idx, t_idx + 1)))
                elif pattern[p_idx + 1] == '+':
                    return (first_match and
                            (is_match(p_idx, t_idx + 1) or is_match(p_idx + 2, t_idx)))
            elif first_match:
                return is_match(p_idx + 1, t_idx + 1)

        return False

    return is_match(0, 0)
